<script>
 import {studio,asset} from '../studio.svelte';import {editor} from '../stores/editor.svelte';import {rgb} from '../api';import {executeCurrentOperation,currentEditorBusy} from '../services/editor.js';import {tasks} from '../stores/tasks.svelte';
 let pending=$state(false),taskId=$state(null),status=$state('');const busy=$derived(pending||currentEditorBusy()||taskId&&['queued','running'].includes(tasks.byId[taskId]?.state));
 async function apply(kind='fit_ratio'){if(!asset()||busy)return;pending=true;status='';try{const p=editor.properties;const result=await executeCurrentOperation([kind==='background'?{kind,color:rgb(p.backgroundColor)}:{kind,ratio:editor.ratio.ratio,orientation:editor.ratio.orientation,long_edge:p.longEdge||undefined,mode:p.mode,background:rgb(p.paddingColor)}],kind==='background'?'设置背景色':'应用图片属性');taskId=result?.task?.id||null;status=result?.task?'已提交，结果保存在版本条':'未提交，请查看对话中的提示';}catch(error){status=error.message;}finally{pending=false;}}
 function edge(event){const input=event.currentTarget;if(!input.validity.valid)return;editor.properties.longEdge=input.value===''?null:Number(input.value);void apply();}
</script>
<section class="props-panel"><h3>输出属性</h3><label>长边像素<input aria-label="长边像素" type="number" min="1" max="16000" step="1" placeholder="原图尺寸" value={editor.properties.longEdge??''} disabled={busy} onchange={edge}/></label><label>适配方式<select aria-label="适配方式" bind:value={editor.properties.mode} disabled={busy} onchange={event=>{editor.properties.mode=event.currentTarget.value;void apply();}}><option value="auto">自动</option><option value="pad">补边</option><option value="crop">裁切</option></select></label><label>补边颜色<input aria-label="补边颜色" type="color" bind:value={editor.properties.paddingColor} disabled={busy} onchange={event=>{editor.properties.paddingColor=event.currentTarget.value;void apply();}}/></label><label>背景色<input aria-label="背景色" type="color" bind:value={editor.properties.backgroundColor} disabled={busy} onchange={event=>{editor.properties.backgroundColor=event.currentTarget.value;void apply('background');}}/></label><p>修改后生成新版本。长边留空时沿用当前图片尺寸；自动适配完整保留主体。</p><h3>掩膜画笔</h3><div role="group" aria-label="掩膜模式"><button class:active={editor.mask.mode==='add'} onclick={()=>{editor.mask.mode='add';studio.tool='mask';studio.paintTool=null;}}>加</button><button class:active={editor.mask.mode==='erase'} onclick={()=>{editor.mask.mode='erase';studio.tool='mask';studio.paintTool=null;}}>擦</button></div><label>笔宽 · [ ]<input aria-label="掩膜画笔大小" type="range" min="2" max="300" step="2" bind:value={editor.mask.size}/></label><p>加：恢复当前图保留的颜色像素；擦：移除透明度。每笔保存为新版本，可撤销。</p><p role="status">{busy?'正在处理当前图片…':status}</p></section>
<style>.props-panel{display:flex;flex-direction:column;gap:12px;font-size:12px}.props-panel label{display:flex;align-items:center;justify-content:space-between;gap:8px}.props-panel input[type=number],.props-panel select{width:120px;min-width:0}.props-panel input[type=color]{width:52px}.props-panel p{font-size:12px;line-height:1.6;color:var(--text-dim);margin:0}.props-panel button.active{background:var(--accent-soft);color:var(--accent)}</style>
